import{_ as i,l,o as e,c as s,v as t,p as n,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"光源功率稳定","description":"","frontmatter":{"title":"光源功率稳定","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/source-power-stability.md","filePath":"litho/source-power-stability.md","lastUpdated":1789023840000}'),E={name:"litho/source-power-stability.md"};function c(_,a,u,A,m,f){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="光源功率稳定" tabindex="-1">光源功率稳定 <a class="header-anchor" href="#光源功率稳定" aria-label="Permalink to &quot;光源功率稳定&quot;">​</a></h1><div class="epigraph"><p>闭环能修慢漂；激光自己不稳，剂量环会饱和或把噪声锁进每场。稳定是光源规格，不是胶的事。</p><footer>—— 接续 [脉冲能量](/litho/pulse-energy-rep-rate)、[剂量传感闭环](/litho/dose-sensor-loop)</footer></div><p><a href="/litho/dose-sensor-loop">上一课</a>把机台环说完。缺口回到激光头：高压、气体、温度如何让 \\(E_p\\) 与中心波长在闭环带宽内足够平。本课收束「从激光到狭缝」，下一单元进物镜。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>放电高压抖、腔温漂、气流不稳，造成脉冲能量与波长的 1/f 噪声。剂量环积分若干脉冲，对场内仍可能留下条纹。波长不稳则焦面抖，像 <a href="/litho/chromatic-bandwidth">色差</a> 的时变版。只加厚胶窗口，不修光源，是用化学买光学。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>激光侧：能量伺服（放电高压）、波长锁（压窄元件微调）、冷却与气体流控。规格：脉冲能量 σ、波长 σ、在目标带宽内的时间。与机台环分工：激光修快变量，剂量环修慢变量与场间。</p>',7)),(e(),n(h,null,{default:o(()=>[p(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20HV%5B%22%E6%94%BE%E7%94%B5%E4%BC%BA%E6%9C%8D%22%5D%20--%3E%20EP%5B%22Ep%20%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20WL%5B%22%E6%B3%A2%E9%95%BF%E9%94%81%22%5D%20--%3E%20LAM%5B%22%E4%B8%AD%E5%BF%83%E6%B3%A2%E9%95%BF%22%5D%0A%20%20EP%20--%3E%20DOSE%5B%22%E5%89%82%E9%87%8F%E7%8E%AF%22%5D%0A%20%20LAM%20--%3E%20FOC%5B%22%E7%84%A6%E9%9D%A2%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">刚换气后的瞬态最差。量产配方应规定「换气后丢弃的脉冲或场数」，不要第一场就当黄金 CD。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>准分子增益对粒子数与温度敏感。伺服把增益钳在工作点。锁波把光栅角度或温度当执行器。两者都有执行器行程：到顶就只剩机台降速。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>物镜加热是下一单元：即使光源完美，镜头仍会自己变。不要把镜头热漂写成激光不稳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光源稳定约束 \\(E_p\\) 与波长的快变量。</li><li>与剂量环分层；换气瞬态要丢弃。</li><li>出处：脉冲与剂量课；准分子伺服通识。</li></ul>',7))])}const D=i(E,[["render",c]]);export{b as __pageData,D as default};
